import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config: any, ctx: any): any {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. Stage / Backdrop Plane for the Title
  // Size: 4.5 x 1.2 units
  const backdropGeo = new PlaneGeometry(4.5, 1.2);
  const backdropMat = new MeshBasicNodeMaterial();

  // Engineered gradient + subtle animated grain in TSL
  const uvNode = uv();
  const grad = smoothstep(0.0, 1.0, uvNode.y);
  const baseColor = vec3(
    parseFloat(`0x${colors.surface.slice(1, 3)}`) / 255,
    parseFloat(`0x${colors.surface.slice(3, 5)}`) / 255,
    parseFloat(`0x${colors.surface.slice(5, 7)}`) / 255
  );
  const inkColor = vec3(
    parseFloat(`0x${colors.ink.slice(1, 3)}`) / 255,
    parseFloat(`0x${colors.ink.slice(3, 5)}`) / 255,
    parseFloat(`0x${colors.ink.slice(5, 7)}`) / 255
  );

  // Mixed background gradient
  const finalColor = mix(inkColor, baseColor, grad);

  backdropMat.colorNode = finalColor;
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  group.add(backdropMesh);

  // Load the feature card image if available, blend it in
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex: any) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      backdropMat.colorNode = mix(
        finalColor, 
        vec3(0.1, 0.1, 0.1), // slightly subdued card presence
        0.4
      );
      backdropMat.needsUpdate = true;
    });
  }

  // 2. Red Accent Bar (the signature signal red #ff2a38 decoration)
  const accentGeo = new PlaneGeometry(0.15, 0.4);
  const accentMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-1.8, 0, 0.01);
  group.add(accentMesh);

  // 3. Render Title Text
  // Get text content from config or fallback to spec
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleString = textItems.find((t: any) => t.role === 'headline')?.text ?? 'Collection';

  // 96px display size maps to roughly 0.45 scene units here
  const textObj = ctx.fontAtlas.createText(titleString, {
    fontSize: 0.45,
    color: colors.paper,
    align: 'left'
  });

  // Position the text nicely to the right of the red accent bar
  textObj.position.set(-1.5, -0.15, 0.02);
  group.add(textObj);

  // 4. Subtle Intro Transition
  const tl = gsap.timeline();
  tl.fromTo(textObj.position, 
    { x: -1.8 },
    { x: -1.5, duration: 0.9, ease: 'power4.out' }
  );
  tl.fromTo(accentMesh.scale,
    { y: 0.001 },
    { y: 1, duration: 0.7, ease: 'power3.out' },
    '<'
  );

  // 5. Cleanup
  group.userData = {
    handlers: {},
    cleanup: () => {
      tl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
    }
  };

  return group;
}
